{
  "segments": [
    {
      "name": "Founder-led B2B SaaS",
      "buyer": "Founder responsible for marketing",
      "market": "Small SaaS businesses preparing a public launch or website update",
      "problem": "An upcoming launch makes collecting and publishing relevant customer proof urgent.",
      "access": "Public launch posts and company websites can identify founders, but a permitted contact route must be verified.",
      "tradeoff": "Founders can approve purchases directly, but willingness to pay depends on an immediate proof gap."
    },
    {
      "name": "Independent course businesses",
      "buyer": "Course creator or business owner",
      "market": "Businesses selling cohort courses",
      "problem": "Enrollment campaigns create a deadline for collecting and sharing learner testimonials.",
      "access": "Public course pages can expose owner contact routes, although campaign timing may be unclear.",
      "tradeoff": "Owners control spending, but willingness to pay may be seasonal."
    },
    {
      "name": "Agency account teams",
      "buyer": "Agency owner or account director",
      "market": "Agencies managing client marketing materials",
      "problem": "Repeated client campaigns require finding the right testimonial across scattered sources.",
      "access": "Agency sites identify decision-makers, but client permissions complicate product evaluation.",
      "tradeoff": "Recurring workflows may support spending, but purchasing and adoption can require client approval."
    }
  ],
  "firstBuyerWhy": {
    "advantage": "A founder with an upcoming launch combines an observable deadline with direct purchasing authority.",
    "risk": "A launch may require only a few existing quotes rather than a recurring testimonial workflow.",
    "runnerUpWinsWhen": "Course owners become the better first buyer when a live enrollment campaign coincides with an accessible pool of recent learners."
  },
  "buyingMotion": "Sales-assisted",
  "paymentPath": {
    "offerKind": "Existing SaaS",
    "monetizationStatus": "Unknown",
    "pricingStatementIds": [],
    "verify": "Check Senja's current official offer, paid capabilities, price and checkout before requesting a paid conversion.",
    "activation": "The prospect receives a genuine customer testimonial through a Senja collection form and makes it ready to share.",
    "adoption": "The prospect repeatedly collects testimonials and retrieves relevant proof for subsequent marketing work.",
    "paidConversion": "Confirm an actual payment for Senja through its verified purchase path, distinct from interest or product usage."
  },
  "firstExperiment": {
    "problem": "Test whether an approaching SaaS launch creates a concrete need to collect and reuse customer testimonials.",
    "identifyProspects": "Research public launch announcements for founder-led B2B SaaS businesses, then verify the founder's role and a public business contact route.",
    "channel": "Direct email",
    "channelRationale": {
      "decision": "Researched email tests deadline-driven pain without requiring an existing audience or integration distribution.",
      "tradeoff": "Manual research limits reach but produces clearer workflow evidence than publishing an asset without known traffic."
    },
    "firstAction": "Verify Senja's current offer, then research a public launch announcement and send a relevant permission-based question through a published business contact route.",
    "activityTarget": {
      "quantity": 4,
      "activity": "Research eligible founders and send individually relevant business emails."
    },
    "resources": {
      "assumedMinutes": 60,
      "preparationMinutes": 15,
      "researchMinutesPerActivity": 6,
      "executionMinutesPerActivity": 3,
      "responseMinutes": 9,
      "activityKind": "Researched contacts",
      "tools": [
        {
          "name": "Public search and company websites",
          "access": "Free/public"
        },
        {
          "name": "Free email account",
          "access": "Free/public"
        }
      ],
      "directSpend": 0,
      "constraints": "Assume zero direct spend for this experiment; use published business contact routes, avoid scraping, and honor opt-outs."
    },
    "commercialLearning": "Learn whether the founder owns the proof workflow, has customers available to ask, and would consider purchasing the verified Senja offer.",
    "continueWhen": "A founder confirms a current collection problem and agrees to use Senja for an actual customer request.",
    "adjustWhen": "Prospects confirm the problem but reveal a different decision-maker, campaign moment or preferred contact route.",
    "stopWhen": "Pause this segment if conversations establish that existing quotes solve the launch need without a recurring collection workflow.",
    "channelDescription": "Find prospects through public launch signals and contact them individually by business email; acquisition is the conversation, not the subsequent product event."
  },
  "alternatives": [
    {
      "channel": "Community template",
      "comparison": {
        "benefit": "A useful testimonial-request template shared in a relevant founder community can support self-service discovery with less individual outreach.",
        "barrier": "Creating the asset and earning posting permission require effort, while unknown community access makes evidence slower."
      },
      "preferWhen": "A relevant community permits useful resource sharing and members visibly discuss testimonial collection.",
      "firstAction": "Check community rules and current discussions before creating a Senja-linked collection workflow template."
    },
    {
      "channel": "Integration ecosystem",
      "comparison": {
        "benefit": "Senja's stated automation capabilities offer a plausible route to workflow-specific discovery and repeated use.",
        "barrier": "Integration access and existing user behavior are unverified, so validating distribution requires more effort and yields slower evidence than direct conversations."
      },
      "preferWhen": "Verified user behavior shows a recurring automation workflow and an ecosystem offers an accessible distribution route.",
      "firstAction": "Check official integration documentation and public ecosystem participation requirements before proposing a workflow resource."
    }
  ],
  "messages": [
    {
      "subject": "Customer proof for your launch",
      "body": "Hi [name], I came across [verified public observation to research]. How are you collecting customer testimonials for the launch? I'm exploring whether Senja's collection forms and shared proof library fit that workflow. Is this something you handle?"
    },
    {
      "subject": "Worth sending a collection workflow?",
      "body": "Hi [name], may I send a short example of collecting a customer testimonial with Senja and preparing it for your marketing? If collecting proof is not a current priority, no problem; I won't keep following up."
    }
  ],
  "positioning": "Senja helps teams collect customer testimonials and keep relevant proof in one place for pitches, pages and posts.",
  "unknowns": [
    "Current pricing, paid capabilities and checkout are unverified.",
    "Founder time, email access and product access are unknown; the experiment uses conservative resource assumptions.",
    "No market research or external verification was performed; segment urgency and willingness to pay remain hypotheses you must test through conversations and purchase behavior."
  ],
  "recommendationBasis": {
    "segments": ["s1", "s4"],
    "acquisitionChannels": ["s2", "s3"],
    "outreachTemplates": ["s1", "s4"],
    "firstTenPlaybook": ["s1", "s2"],
    "thirtyDayPlan": ["s3", "s4"]
  },
  "contractVersion": "2"
}

